using System.Collections.Generic;
using UnityEngine;

namespace Apex.Rendering
{
    /// <summary>
    /// Creates material instances from template materials stored in Resources/Materials.
    /// Templates are generated by the editor pipeline with fixed keyword sets so that the required
    /// URP shader variants are always included in builds.
    /// </summary>
    public static class MaterialLibrary
    {
        private static readonly Dictionary<string, Material> Templates = new Dictionary<string, Material>();
        private static readonly Dictionary<string, Texture2D> Textures = new Dictionary<string, Texture2D>();

        private static readonly int BaseMap = Shader.PropertyToID("_BaseMap");
        private static readonly int BaseColor = Shader.PropertyToID("_BaseColor");
        private static readonly int Metallic = Shader.PropertyToID("_Metallic");
        private static readonly int Smoothness = Shader.PropertyToID("_Smoothness");
        private static readonly int BumpMap = Shader.PropertyToID("_BumpMap");
        private static readonly int BumpScale = Shader.PropertyToID("_BumpScale");
        private static readonly int EmissionColor = Shader.PropertyToID("_EmissionColor");
        private static readonly int Cutoff = Shader.PropertyToID("_Cutoff");

        public static Material Template(string name)
        {
            if (Templates.TryGetValue(name, out var m) && m != null) return m;
            m = Resources.Load<Material>("Materials/" + name);
            if (m == null)
            {
                Debug.LogError($"[MaterialLibrary] Missing template material '{name}'. Run Apex > Setup Project.");
                var shader = Shader.Find("Universal Render Pipeline/Lit");
                if (shader == null) shader = Shader.Find("Standard");
                m = new Material(shader);
            }
            Templates[name] = m;
            return m;
        }

        public static Texture2D Tex(string name)
        {
            if (Textures.TryGetValue(name, out var t) && t != null) return t;
            t = Resources.Load<Texture2D>("Textures/" + name);
            if (t == null) Debug.LogWarning($"[MaterialLibrary] Missing texture '{name}'");
            Textures[name] = t;
            return t;
        }

        public static Material Lit(Color color, float metallic = 0f, float smoothness = 0.5f, Texture tex = null, Vector2? tiling = null)
        {
            var m = new Material(Template("M_Lit"));
            Configure(m, color, metallic, smoothness, tex, tiling);
            return m;
        }

        public static Material LitNormal(Color color, float metallic, float smoothness, Texture tex, Texture normal, float normalStrength, Vector2? tiling = null)
        {
            var m = new Material(Template("M_LitNormal"));
            Configure(m, color, metallic, smoothness, tex, tiling);
            if (normal != null)
            {
                m.SetTexture(BumpMap, normal);
                m.SetTextureScale(BumpMap, tiling ?? Vector2.one);
            }
            m.SetFloat(BumpScale, normalStrength);
            return m;
        }

        public static Material Emissive(Color baseColor, Color emission, float intensity, Texture tex = null, Vector2? tiling = null)
        {
            var m = new Material(Template("M_LitEmissive"));
            Configure(m, baseColor, 0f, 0.6f, tex, tiling);
            m.SetColor(EmissionColor, emission * intensity);
            if (tex != null) m.SetTexture("_EmissionMap", tex);
            m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
            return m;
        }

        public static void SetEmission(Material m, Color emission, float intensity)
        {
            m.SetColor(EmissionColor, emission * intensity);
        }

        public static Material Cutout(Texture tex, Color tint, float cutoff = 0.5f, Vector2? tiling = null, float smoothness = 0.2f)
        {
            var m = new Material(Template("M_LitCutout"));
            Configure(m, tint, 0f, smoothness, tex, tiling);
            m.SetFloat(Cutoff, cutoff);
            return m;
        }

        public static Material Transparent(Color color, float smoothness = 0.95f, float metallic = 0f)
        {
            var m = new Material(Template("M_LitTransparent"));
            Configure(m, color, metallic, smoothness, null, null);
            return m;
        }

        public static Material Unlit(Color color, Texture tex = null)
        {
            var m = new Material(Template("M_Unlit"));
            m.SetColor(BaseColor, color);
            if (tex != null) m.SetTexture(BaseMap, tex);
            return m;
        }

        public static Material Particle(Texture tex, bool additive)
        {
            var m = new Material(Template(additive ? "M_ParticleAdditive" : "M_ParticleAlpha"));
            if (tex != null) m.SetTexture(BaseMap, tex);
            return m;
        }

        // ------------------------------------------------------------------ PBR (visual overhaul)

        private static readonly int MetallicGlossMap = Shader.PropertyToID("_MetallicGlossMap");
        private static readonly int OcclusionMap = Shader.PropertyToID("_OcclusionMap");
        private static readonly int OcclusionStrength = Shader.PropertyToID("_OcclusionStrength");
        private static readonly int DetailAlbedoMap = Shader.PropertyToID("_DetailAlbedoMap");

        /// <summary>
        /// Full PBR material from a processed set in Resources/Textures/pbr (albedo, normal, metallic/smoothness, AO).
        /// smoothness acts as a multiplier on the smoothness map.
        /// </summary>
        public static Material PBR(string set, Vector2 tiling, Color tint, float smoothness = 1f, float normalStrength = 1f)
        {
            var m = new Material(Template("M_LitPBR"));
            ApplySet(m, set, tiling, tint, smoothness, normalStrength);
            return m;
        }

        /// <summary>Road surface: PBR asphalt plus a large-scale wear / repair / tar-snake detail layer.</summary>
        public static Material Road(Vector2 tiling, Vector2 wearTiling, Color tint)
        {
            var m = new Material(Template("M_Road"));
            ApplySet(m, "road", tiling, tint, 1f, 1f);
            var wear = Tex("pbr/road_wear");
            if (wear != null)
            {
                m.SetTexture(DetailAlbedoMap, wear);
                m.SetTextureScale(DetailAlbedoMap, wearTiling);
            }
            return m;
        }

        private static void ApplySet(Material m, string set, Vector2 tiling, Color tint, float smoothness, float normalStrength)
        {
            m.SetColor(BaseColor, tint);
            var albedo = Tex($"pbr/{set}_albedo");
            var normal = Tex($"pbr/{set}_n");
            var ms = Tex($"pbr/{set}_ms");
            var ao = Tex($"pbr/{set}_ao");
            if (albedo != null) { m.SetTexture(BaseMap, albedo); m.SetTextureScale(BaseMap, tiling); }
            if (normal != null) m.SetTexture(BumpMap, normal);
            m.SetFloat(BumpScale, normalStrength);
            if (ms != null) m.SetTexture(MetallicGlossMap, ms);
            m.SetFloat(Smoothness, smoothness);
            m.SetFloat(Metallic, 1f);
            if (ao != null) { m.SetTexture(OcclusionMap, ao); m.SetFloat(OcclusionStrength, 1f); }
            else m.SetFloat(OcclusionStrength, 0f);
        }

        /// <summary>Multi-layer automotive paint: metallic base with flake normal and a clear coat.</summary>
        public static Material CarPaint(Texture livery, float metallic = 0.55f, float baseSmoothness = 0.62f)
        {
            var m = new Material(Template("M_CarPaint"));
            m.SetColor(BaseColor, Color.white);
            if (livery != null) m.SetTexture(BaseMap, livery);
            m.SetFloat(Metallic, metallic);
            m.SetFloat(Smoothness, baseSmoothness);
            m.SetTextureScale(BumpMap, new Vector2(18f, 9f));
            return m;
        }

        public static Material UnlitTransparent(Texture tex, Color color)
        {
            var m = new Material(Template("M_UnlitTransparent"));
            m.SetColor(BaseColor, color);
            if (tex != null) m.SetTexture(BaseMap, tex);
            return m;
        }

        private static void Configure(Material m, Color color, float metallic, float smoothness, Texture tex, Vector2? tiling)
        {
            m.SetColor(BaseColor, color);
            m.SetFloat(Metallic, metallic);
            m.SetFloat(Smoothness, smoothness);
            if (tex != null)
            {
                m.SetTexture(BaseMap, tex);
                m.SetTextureScale(BaseMap, tiling ?? Vector2.one);
            }
        }
    }
}
